package com.example.jebwool;

import net.minecraft.world.item.DyeColor;
import net.minecraft.world.level.block.BedBlock;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.state.BlockState;

/**
 * jeb_ bed. This is a normal bed (sleeping, respawn point, etc., just like vanilla),
 * but with a different model: the model and textures are taken from the vanilla white bed and cycle through 16 colors.
 * The models are generated by the tools/generate-assets.ps1 script.
 */
public class JebBedBlock extends BedBlock {
    public JebBedBlock(Properties properties) {
        // The color is required by the parent constructor, but it does not affect the visible result here.
        super(DyeColor.WHITE, properties);
    }

    /** Beds are rendered as regular JSON models (as of 26.2, beds no longer use a block entity). */
    @Override
    protected RenderShape getRenderShape(BlockState state) {
        return RenderShape.MODEL;
    }
}
